<template><CoopTaskSheet :show="show" title="交付详情" :subtitle="lead.status_label || coopStatusLabels[lead.status]" :busy="busy" full @close="$emit('close')"><CoopState v-if="loading || error" :loading="loading" :error="error" @retry="$emit('reload')" /><template v-else-if="lead.id"><view v-if="lead.attention_reasons?.length" class="coop-task-rule"><view v-for="reason in lead.attention_reasons" :key="reason">{{ reason }}</view></view><view class="coop-state-heading"><view>{{ lead.can_accept ? '等待你接单' : lead.can_report ? '联系客户，反馈结果' : lead.can_pay ? '已成交，等待付佣' : lead.status_label || coopStatusLabels[lead.status] }}</view><text>{{ lead.can_accept ? '接单后开放必要联系方式与附件' : '客户货款由客户与门店直接结算' }}</text></view><view class="coop-form-section"><view class="coop-section-title">客户需求<text>{{ businessLabels[lead.business_type] || '购买' }}</text></view><view class="coop-customer-contact"><view><view class="coop-customer-name">{{ lead.customer_name || '客户' }}</view><view class="coop-contact-number">{{ lead.mobile || '接单后查看联系电话' }}</view></view><view v-if="canCall" class="coop-call" @tap="call"><u-icon name="phone" size="25" color="var(--primary-color, #d93833)" /><text>联系客户</text></view></view><view class="coop-detail-region">{{ lead.region_text }}</view><CoopModels :items="lead.models || []" /><view v-if="lead.remark" class="coop-detail-remark">{{ lead.remark }}</view><view v-if="lead.attachments?.length" class="coop-detail-images"><image v-for="url in lead.attachments" :key="url" :src="img(url)" mode="aspectFill" @tap="preview(url)" /></view></view><view class="coop-form-section"><view class="coop-section-title">交付门店</view><view class="coop-detail-shop"><text>发布方</text><text>{{ lead.publisher?.name || '—' }}</text></view><view class="coop-detail-shop"><text>承接方</text><text>{{ lead.receiver?.name || '尚未选定' }}</text></view></view><view v-if="lead.status === 'unpaid' || lead.status === 'paid'" class="coop-form-section"><view class="coop-section-title">协作佣金</view><view class="coop-detail-shop"><text>{{ lead.status === 'paid' ? '已付佣金' : '待付佣金' }}</text><text>{{ coopMoney(lead.commission_amount) }}</text></view><view v-if="lead.status === 'paid'" class="coop-detail-shop"><text>发布方收益</text><text>{{ coopMoney(lead.net_amount) }}</text></view></view><view class="coop-task-rule">成交后支付协作佣金，最低 {{ coopMoney(config.commission_minimum || 50) }}；未成交不收费。认证与库存匹配不代表平台担保或锁货。</view><view class="coop-form-section"><view class="coop-fold-title" @tap="history = !history">编号与处理记录<u-icon :name="history ? 'arrow-up' : 'arrow-down'" size="12" color="#89939f" /></view><template v-if="history"><view class="coop-muted coop-detail-remark">{{ lead.lead_no }} · {{ coopDate(lead.create_time) }}</view><view v-for="item in lead.history || []" :key="item.id || item.create_time" class="coop-history-item"><text>{{ item.content || item.remark || item.action_label || item.action }}</text><text>{{ coopDate(item.create_time) }}</text></view><view v-if="!lead.history?.length" class="coop-muted">暂无处理记录</view></template></view></template><template #footer><view v-if="lead.id && !loading && !error" class="coop-footer-actions"><template v-if="lead.can_accept"><view class="coop-secondary"><u-button shape="circle" text="暂不承接" :disabled="busy" @click="$emit('action', 'reject')" /></view><view class="coop-primary"><u-button type="primary" shape="circle" text="接受交付" :disabled="busy" :loading="busy" @click="$emit('action', 'accept')" /></view></template><template v-else-if="lead.can_report"><view class="coop-secondary"><u-button shape="circle" text="未成交" :disabled="busy" @click="$emit('action', 'no_deal')" /></view><view class="coop-primary"><u-button type="primary" shape="circle" text="已成交，去付佣" :disabled="busy" :loading="busy" @click="$emit('action', 'deal')" /></view></template><view v-else-if="lead.can_pay" class="coop-primary"><u-button type="primary" shape="circle" text="支付协作佣金" :disabled="busy" @click="$emit('pay')" /></view><view v-else-if="lead.can_assign" class="coop-primary"><u-button type="primary" shape="circle" text="选择交付门店" :disabled="busy" @click="$emit('select')" /></view><template v-else-if="lead.can_withdraw"><view class="coop-secondary"><u-button shape="circle" text="撤回交付" :disabled="busy" @click="$emit('action', 'withdraw')" /></view><view class="coop-primary"><u-button type="primary" shape="circle" text="返回列表" @click="$emit('close')" /></view></template><view v-else class="coop-primary"><u-button shape="circle" text="返回列表" @click="$emit('close')" /></view></view></template></CoopTaskSheet></template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { img } from '@/utils/common'
import { businessLabels, coopDate, coopMoney, coopStatusLabels, type CoopRow, type LeadAction } from '../../api/cooperation'
import CoopTaskSheet from './CoopTaskSheet.vue'
import CoopState from './CoopState.vue'
import CoopModels from './CoopModels.vue'
const props = withDefaults(defineProps<{ show: boolean; lead: CoopRow; config: CoopRow; loading?: boolean; busy?: boolean; error?: string }>(), { loading: false, busy: false, error: '' })
defineEmits<{ (event: 'close' | 'reload' | 'pay' | 'select'): void; (event: 'action', value: LeadAction): void }>()
const history = ref(false), canCall = computed(() => /^1\d{10}$/.test(String(props.lead.mobile || '')))
function call() { if (canCall.value) uni.makePhoneCall({ phoneNumber: String(props.lead.mobile), fail: () => uni.showToast({ title: '未能拨打，请手动联系', icon: 'none' }) }) }
function preview(url: string) { uni.previewImage({ urls: (props.lead.attachments || []).map(img), current: img(url) }) }
watch(() => props.show, () => { history.value = false })
</script>
